#include <iostream>
#include <string>

int main()
{
  std::string line;
  std::getline(std::cin, line);

  std::string upper = line;
  for (char& ch : upper) {
    if (ch >= 'a' && ch <= 'z') {
      ch = static_cast<char>(ch - 'a' + 'A');
    }
  }

  std::cout << line.size() << '\n' << upper << '\n';
}

